// Valida Authorization: Bearer <SYNC_SECRET> si viene cabecera o si está configurado en n8n
const firstItem = $input.first().json;
const headers = firstItem.headers || {};
const auth = headers.authorization || headers.Authorization || firstItem.authorization || '';
const secret = ($env.SYNC_SECRET || '').trim();
if (secret && auth) {
  if (!auth.startsWith('Bearer ') || auth.slice(7).trim() !== secret) {
    throw new Error('Unauthorized');
  }
}
const body = firstItem.body || firstItem;
const url = String(body.url || body.q || body.modelId || '').trim();
if (!url) throw new Error('Missing url');
return [{ json: { url } }];

const urlOrId = String($input.item.json.url || '').trim();
let id = '';
const numMatch = urlOrId.match(/^#?(\d+)$/);
if (numMatch) {
  id = numMatch[1];
} else {
  const match = urlOrId.match(/(?:makerworld\.com\/[^\s]*\/models\/|models\/)(\d+)/i) || urlOrId.match(/(\d+)/);
  if (!match) throw new Error('Entrada no válida. Pon ID o URL.');
  id = match[1];
}
return { json: { externalId: id } };

const htmlStr = $input.item.json?.solution?.response || "";
const preMatch = htmlStr.match(/<pre[^>]*>([\s\S]*?)<\/pre>/i);
let rawJson = preMatch ? preMatch[1] : (htmlStr.match(/<body[^>]*>(.*?)<\/body>/is)?.[1] || htmlStr);
rawJson = rawJson.replace(/<[^>]*>?/gm, '').trim();
try {
    const data = JSON.parse(rawJson);
    const instances = data.instances || [];
    if (!instances.length) throw new Error('No instances found.');
    const defaultId = data.defaultInstanceId ? String(data.defaultInstanceId) : '';
    const profiles = instances.map(ins => {
      const plates = ((ins.extention || {}).modelInfo || {}).plates || [];
      const platesGrams = plates.reduce((s, p) => s + (Number(p.weight) || 0), 0);
      const platesSeconds = plates.reduce((s, p) => s + (Number(p.prediction) || 0), 0);
      const grams = Number(ins.weight) || platesGrams;
      const seconds = Number(ins.prediction) || platesSeconds;
      const profileIdStr = String(ins.id || ins.profileId || '');
      return {
        id: profileIdStr,
        title: ins.title || ins.titleTranslated || 'Perfil sin nombre',
        name: ins.name || '',
        grams: Number.isFinite(grams) ? Number(grams.toFixed(2)) : 0,
        hours: Number.isFinite(seconds) ? Number((seconds / 3600).toFixed(3)) : 0,
        plateCount: plates.length || 1,
        isDefault: Boolean(ins.isDefault || (defaultId && defaultId === profileIdStr)),
        needAms: Boolean(ins.needAms),
        colorCount: Number(ins.materialColorCnt) || Number(ins.materialCnt) || 1,
        cover: ins.cover || (ins.extention?.modelInfo?.plates?.[0]?.top_picture?.url) || null,
      };
    }).filter(p => p.grams > 0 || p.hours > 0);
    if (!profiles.length) throw new Error('No stats.');
    if (!profiles.some(p => p.isDefault)) {
      const def = profiles.find(p => p.id === defaultId);
      if (def) def.isDefault = true;
      else profiles[0].isDefault = true;
    }
    return { json: { profiles } };
} catch (e) {
    throw new Error("Parse error: " + e.message);
}
